type ContactMethod = "direct" | "email" | "whatsapp" | "sms" | "phone";
type LinkMode = "capture" | "redirect" | "both";
type LeadStatus = "new" | "contacted" | "sent_to_seller" | "in_follow_up" | "won" | "lost";
type PropertyForm = { slug: string; title: string; address: string; city: string; zone: string; province: string; country: string; type: string; price: string; priceValue: number; referenceCode: string; sourcePrice: string; sourceUrl: string; sortOrder: number; bedrooms: number; bathrooms: number; surface: number; description: string; descriptionMode: "auto" | "compact" | "scroll" | "full"; descriptionHeight: number; featured: boolean; imageUrl: string; galleryUrls: string; features: string; latitude: string; longitude: string; tag: string; status: "draft" | "published"; linkMode: LinkMode; vendorId: string; externalUrl: string; referralParameter: string; referralCode: string; };
type VendorForm = { name: string; email: string; phone: string; contactMethod: ContactMethod; contactValue: string; referralParameter: string; referralCode: string; attributionNote: string; publicationAuthorized: boolean; authorizationNote: string; };
type OperationForm = { leadId: string; propertyId: string; vendorId: string; operationType: "property" | "construction" | "product"; clientName: string; title: string; address: string; city: string; province: string; country: string; salePrice: number; commissionPercent: number; commissionStatus: "expected" | "pending" | "paid" | "cancelled"; notes: string; };
type ListedProperty = Omit<PropertyForm, "vendorId" | "featured"> & { id: number; vendorId: number | null; externalUrl: string | null; referralCode: string | null; featured: number; };
type Vendor = { id: number; name: string; email: string | null; phone: string | null; contactMethod: ContactMethod; contactValue: string | null; referralParameter: string; referralCode: string; attributionNote: string | null; publicationAuthorized: number; authorizationNote: string | null; };
type Lead = { id: number; leadType: "property" | "construction" | "product"; propertyId: number | null; name: string; email: string; phone: string | null; preferredLocation: string | null; preferredProvince: string | null; latitude: string | null; longitude: string | null; budget: string | null; referenceImages: string | null; attributionCode: string; message: string; status: LeadStatus; createdAt: Date; privacyAcceptedAt?: Date | null; };
type Operation = { id: number; clientName: string; title: string; salePrice: number; commissionPercent: number; commissionAmount: number; commissionStatus: "expected" | "pending" | "paid" | "cancelled"; city: string; province: string; createdAt: Date; };
type SettingsForm = { bannerText: string; bannerBackground: string; bannerColor: string; bannerHeight: number; bannerRotationSeconds: number; cardStyle: "flat" | "three_d" | "shadow" | "frame" | "grid" | "minimal"; enabledLocales: string; contactPhone: string; cryptoEnabled: boolean; cryptoAcceptedTypes: string[]; reservationButtonText: string; reservationButtonBackground: string; reservationButtonColor: string; officeMapEmbedUrl: string; relatedPropertiesCount: number; whatsappEnabled: boolean; whatsappPhone: string; whatsappMessage: string; whatsappStyle: WhatsAppWidgetStyle; whatsappAnimationEnabled: boolean; whatsappAnimationSeconds: number; };
type VisitInteraction = { id: string; kind: "visit" | "click"; propertyId: number | null; channel: string | null; locale: string | null; createdAt: Date };

const parseCryptoList = (source?: string | null): string[] => { try { const parsed = JSON.parse(source || "[]"); return Array.isArray(parsed) ? parsed.filter((item): item is string => typeof item === "string") : [...CRYPTO_OPTIONS]; } catch { return [...CRYPTO_OPTIONS]; } };

const blankProperty = (): PropertyForm => ({ slug: "", title: "", address: "", city: "", zone: "", province: "", country: "España", type: "Piso", price: "", priceValue: 0, bedrooms: 1, bathrooms: 1, surface: 60, description: "", descriptionMode: "auto", descriptionHeight: 260, featured: false, imageUrl: "", galleryUrls: "", features: "", latitude: "", longitude: "", tag: "Nueva oportunidad", status: "draft", linkMode: "capture", vendorId: "", externalUrl: "", referenceCode: "", sourcePrice: "", sourceUrl: "", sortOrder: 0, referralParameter: "ref", referralCode: "MARTINEZ" });
const blankVendor = (): VendorForm => ({ name: "", email: "", phone: "", contactMethod: "direct", contactValue: "", referralParameter: "ref", referralCode: "MARTINEZ", attributionNote: "", publicationAuthorized: false, authorizationNote: "" });
const blankOperation = (): OperationForm => ({ leadId: "", propertyId: "", vendorId: "", operationType: "property", clientName: "", title: "", address: "", city: "", province: "", country: "España", salePrice: 0, commissionPercent: 0, commissionStatus: "expected", notes: "" });
const toSlug = (value: string) => value.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "").slice(0, 180);
const formatDate = (date: Date) => new Intl.DateTimeFormat("es-ES", { dateStyle: "medium", timeStyle: "short" }).format(new Date(date));
const euro = (amount: number) => new Intl.NumberFormat("es-ES", { style: "currency", currency: "EUR", maximumFractionDigits: 0 }).format(amount);
const preferredImage = (imageUrl: string, galleryUrls?: string | null) => { try { const items = JSON.parse(galleryUrls || "[]"); const first = Array.isArray(items) ? items.find((item) => typeof item === "string" && /^https?:\/\//.test(item)) : undefined; return first || imageUrl; } catch { return imageUrl; } };

